#!/usr/bin/env python3
"""Single-file launcher for HX5X5X5X AI STUDIO.
Requires Python 3, Node.js, and npm on the hosting container.
The default panel login password is embedded below; change it before public deployment.
"""
import os, sys, shutil, subprocess, signal
from pathlib import Path

ROOT = Path(__file__).resolve().parent / "_hx5x5x5x_runtime"
SERVER_JS_B64 = ""
PACKAGE_JSON_B64 = "ewogICJuYW1lIjogIkh4NXg1eDV4IiwKICAidmVyc2lvbiI6ICIxLjAuMCIsCiAgInByaXZhdGUiOiB0cnVlLAogICJtYWluIjogInNlcnZlci5qcyIsCiAgInNjcmlwdHMiOiB7ICJzdGFydCI6ICJub2RlIHNlcnZlci5qcyIgfSwKICAiZGVwZW5kZW5jaWVzIjogewogICAgIkBvcGVuYWkvY29kZXgiOiAibGF0ZXN0IiwKICAgICJmZm1wZWctc3RhdGljIjogIl41LjIuMCIKICB9Cn0K"


DEFAULT_APP_PASSWORD = "taki"

def main():
    os.environ.setdefault("APP_PASSWORD", DEFAULT_APP_PASSWORD)
    if not os.environ.get("APP_PASSWORD"):
        print("[ERROR] Set APP_PASSWORD in your hosting environment, then restart.", flush=True)
        return 1

    node = shutil.which("node")
    npm = shutil.which("npm")
    if not node or not npm:
        print("[ERROR] Node.js and npm are required. This Python launcher cannot run on a Python-only container.", flush=True)
        print("Install/enable Node.js in the hosting image or use a Node.js server.", flush=True)
        return 1

    ROOT.mkdir(parents=True, exist_ok=True)
    (ROOT / "server.js").write_bytes(__import__("base64").b64decode(SERVER_JS_B64))
    (ROOT / "package.json").write_bytes(__import__("base64").b64decode(PACKAGE_JSON_B64))

    codex_bin = ROOT / "node_modules" / ".bin" / ("codex.cmd" if os.name == "nt" else "codex")
    if not codex_bin.exists():
        print("[SETUP] Installing Codex CLI and optional ffmpeg package...", flush=True)
        result = subprocess.run(
            [npm, "install", "--no-audit", "--no-fund"],
            cwd=ROOT, env=os.environ.copy()
        )
        if result.returncode != 0:
            print("[ERROR] npm install failed. Check network access and available disk space.", flush=True)
            return result.returncode

    env = os.environ.copy()
    env.setdefault("PORT", "3000")
    print("[START] Launching HX5X5X5X AI STUDIO...", flush=True)
    proc = subprocess.Popen([node, "server.js"], cwd=ROOT, env=env)

    def stop(signum, frame):
        if proc.poll() is None:
            proc.terminate()
    for sig in (getattr(signal, "SIGTERM", None), getattr(signal, "SIGINT", None)):
        if sig is not None:
            try: signal.signal(sig, stop)
            except Exception: pass
    return proc.wait()

if __name__ == "__main__":
    raise SystemExit(main())
